"""Сборка компактных лексиконов docrec/lexicons/<doctype>/<field>.txt.gz из ПУБЛИЧНЫХ источников (никаких данных с фото пользователей):
  - классификаторы/нормативка: ТР ТС 018/2011 и ОКОФ (типы ТС), приказ МВД №1121 (форма СТС), ПДД РФ/Конвенция 1968 (категории ВУ),
    Положение об удостоверении тракториста-машиниста (кат. A I-IV, B-F), перечень субъектов РФ (ст. 65 Конституции), месяцы;
  - словари OpenCorpora (через pymorphy3-dicts-ru, леммы с грамматемами Name/Surn/Patr/Geox) и ru_RU-провайдеры Faker (MIT) — имена, отчества, города;
  - собственные короткие списки (популярные марки в РФ, цвета, слова реквизитов).
Формат строки файла: «каноническое значение[|синоним|синоним]» (# — комментарий). Запуск: python tools/build_lexicons.py [--pm /tmp/pm_names.json] [--faker /tmp/fk]
Без внешних файлов собираются только ручные списки (имена — из --pm/--faker, если указаны)."""
import argparse, gzip, json, os, re, sys
OUT = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "docrec", "lexicons")


def put(path, lines):
    p = os.path.join(OUT, path + ".txt.gz"); os.makedirs(os.path.dirname(p), exist_ok=True)
    seen, out = set(), []
    for l in lines:
        l = l.strip()
        if l and l not in seen: seen.add(l); out.append(l)
    with gzip.GzipFile(p, "wb", 9, mtime=0) as f: f.write(("\n".join(out) + "\n").encode("utf-8"))
    return len(out), os.path.getsize(p)


