def load_names(pm_path, faker_dir):
    names = {"first": set(), "patr": set(), "sur": set(), "geo": set(), "faker_cities": set(), "male": set(), "female": set()}
    if faker_dir:
        sys.path.insert(0, faker_dir)
        from faker.providers.person.ru_RU import Provider as P
        from faker.providers.address.ru_RU import Provider as A
        names["first"] |= {x.upper() for x in P.first_names}; names["male"] |= {x.upper() for x in P.first_names_male}; names["female"] |= {x.upper() for x in P.first_names_female}
        names["patr"] |= {x.upper() for x in P.middle_names}; names["sur"] |= {x.upper() for x in P.last_names}
        names["faker_cities"] |= {x.upper() for x in A.city_names}
    if pm_path and os.path.exists(pm_path):
        d = json.load(open(pm_path, encoding="utf-8"))
        names["first"] |= {x.upper() for x in d["Name"] if 2 < len(x) < 14 and re.fullmatch(r"[а-яё]+", x)}
        names["sur"] |= {x.upper() for x in d["Surn"] if 3 < len(x) < 18 and re.fullmatch(r"[а-яё\-]+", x)}
        names["geo"] |= {x.upper() for x in d["Geox"] if 3 < len(x) < 22 and re.fullmatch(r"[а-яё\-]+", x)}
    return names


def patronymics(male):
    out = set()
    for n in male:
        n = n.upper()
        if n.endswith(("Й", "Ь")):
            if n.endswith("ЕЙ"): b = n[:-2] + "ЕЕВИЧ"
            elif n.endswith("ИЙ"):
                b = n[:-2] + "ИЕВИЧ"; out.add(b); out.add(b[:-2] + "НА"); b = n[:-2] + "ЬЕВИЧ"
            elif n.endswith("Ь"): b = n[:-1] + "ЕВИЧ"
            else: b = n[:-1] + "ЕВИЧ"
        elif n.endswith("А") or n.endswith("Я"):
            if n in ("ИЛЬЯ", "ЛУКА", "КУЗЬМА", "ФОМА", "САВВА", "НИКИТА", "ДАНИЛА", "ЯКОВ"): continue
            b = n[:-1] + "ИЧ"
        elif n[-1] in "БВГДЖЗКЛМНПРСТФХЦЧШЩ": b = n + "ОВИЧ"
        else: continue
        out.add(b); out.add(b[:-2] + "НА")
    special = {"ИЛЬИЧ": "ИЛЬИНИЧНА", "НИКИТИЧ": "НИКИТИЧНА", "ЛУКИЧ": "ЛУКИНИЧНА", "КУЗЬМИЧ": "КУЗЬМИНИЧНА", "ФОМИЧ": "ФОМИНИЧНА", "САВВИЧ": "САВВИШНА"}
    out |= set(special) | set(special.values()) | {"ОГЛЫ", "КЫЗЫ", "ОГЛУ"}
    return out


def adj_forms(word):
    """Падежные формы прилагательных регионов: Саратовская -> САРАТОВСКОЙ/САРАТОВСКУЮ; Краснодарский -> КРАСНОДАРСКОГО/КРАСНОДАРСКОМ."""
    w = word.upper(); out = {w}
    if w.endswith("АЯ"): out |= {w[:-2] + e for e in ("ОЙ", "УЮ", "АЯ")}
    elif w.endswith("ИЙ") or w.endswith("ЫЙ") or w.endswith("ОЙ"): out |= {w[:-2] + e for e in ("ОГО", "ОМУ", "ОМ", "ИЙ", "ЫЙ", "ОЙ", "ОГО")}
    elif w.endswith("ОЕ"): out |= {w[:-2] + e for e in ("ОГО", "ОМ", "ОЕ")}
    elif w.endswith("КАЯ"): pass
    return out


def noun_forms(word):
    w = word.upper(); out = {w}
    if re.fullmatch(r"[А-ЯЁ\-]+", w) and " " not in w:
        if w[-1] in "БВГДЖЗКЛМНПРСТФХЦЧШЩ": out |= {w + e for e in ("А", "У", "Е", "ОМ")}
        elif w[-1] == "А": out |= {w[:-1] + e for e in ("Ы", "Е", "У", "ОЙ")}
        elif w[-1] == "Я": out |= {w[:-1] + e for e in ("И", "Е", "Ю")}
        elif w[-1] == "Ь": out |= {w[:-1] + e for e in ("И", "Я", "Ю", "Е")}
        elif w[-1] == "Й": out |= {w[:-1] + e for e in ("Я", "Ю", "Е")}
        elif w[-1] == "О": out |= {w[:-1] + e for e in ("А", "У", "Е")}
    return out


def main():
    ap = argparse.ArgumentParser(); ap.add_argument("--pm"); ap.add_argument("--faker"); ap.add_argument("--exclude", help="JSON-список строк, которые нельзя включать в словарь фамилий (локальный файл, не коммитится)"); a = ap.parse_args()
    N = load_names(a.pm, a.faker); stats = {}
    def rec(k, lines): stats[k] = put(k, lines)
    male = N["male"] | {x for x in """АЛЕКСАНДР АЛЕКСЕЙ АНАТОЛИЙ АНДРЕЙ АНТОН АРКАДИЙ АРСЕНИЙ АРТЁМ АРТЕМ АРТУР БОРИС ВАДИМ ВАЛЕНТИН ВАЛЕРИЙ ВАСИЛИЙ ВИКТОР ВИТАЛИЙ ВЛАДИМИР ВЛАДИСЛАВ ВЯЧЕСЛАВ ГЕННАДИЙ ГЕОРГИЙ ГЕРМАН ГРИГОРИЙ ДАНИИЛ ДАНИЛА ДЕНИС ДМИТРИЙ ЕВГЕНИЙ ЕГОР ИВАН ИГОРЬ ИЛЬЯ КИРИЛЛ КОНСТАНТИН ЛЕВ ЛЕОНИД МАКСИМ МИХАИЛ НИКИТА НИКОЛАЙ ОЛЕГ ПАВЕЛ ПЁТР ПЕТР РОМАН РУСЛАН СВЯТОСЛАВ СЕМЁН СЕМЕН СЕРГЕЙ СТАНИСЛАВ СТЕПАН ТИМОФЕЙ ТИМУР ФЁДОР ФЕДОР ФЕЛИКС ЮРИЙ ЯКОВ ЯРОСЛАВ ЭДУАРД ЭМИЛЬ АЗАМАТ АЙРАТ АЛЬБЕРТ АНВАР БАХТИЯР ДАМИР ИЛЬДАР ИЛЬЯС РАВИЛЬ РАДИК РАМИЛЬ РАШИД РИНАТ РУСТАМ ФАРИД ФАРИТ ХАЛИЛ ШАМИЛЬ ЭЛЬДАР ЮСУФ""".split()}
    first = N["first"] | male
    fem = N["female"] | {x for x in """АДЕЛИНА АЛЕКСАНДРА АЛИНА АЛИСА АЛЛА АЛЬБИНА АНАСТАСИЯ АНГЕЛИНА АННА АНТОНИНА БОГДАНА ВАЛЕНТИНА ВАЛЕРИЯ ВАРВАРА ВЕРА ВЕРОНИКА ВИКТОРИЯ ГАЛИНА ДАРЬЯ ДИАНА ЕВА ЕВГЕНИЯ ЕКАТЕРИНА ЕЛЕНА ЕЛИЗАВЕТА ЗИНАИДА ЗОЯ ИННА ИРИНА КИРА КРИСТИНА КСЕНИЯ ЛАРИСА ЛИДИЯ ЛИЛИЯ ЛИЮБОВЬ ЛЮБОВЬ ЛЮДМИЛА МАРГАРИТА МАРИНА МАРИЯ НАДЕЖДА НАТАЛЬЯ НИНА ОКСАНА ОЛЬГА ПОЛИНА РАИСА РИММА СВЕТЛАНА СОФИЯ ТАМАРА ТАТЬЯНА УЛЬЯНА ЮЛИЯ ЮЛИАНА ЯНА АЙГУЛЬ ГУЛЬНАРА ЗАРИНА ЛЕЙЛА ЛИЛИЯ РОЗА РЕГИНА ЭЛЬВИРА ЭЛЬМИРА ЮЛИЯ""".split()}
    first |= fem
    rec("shared/first_names", sorted(first))
    pat = patronymics(male) | N["patr"]
    rec("shared/patronymics", sorted(pat))
    excl = {x.upper() for x in json.load(open(a.exclude, encoding="utf-8"))} if a.exclude else set()
